// Generates src/content/pages/index.ts from every page file in that folder
// that exports `pages`. Runs automatically before dev/build.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";

const dir = new URL("../src/content/pages/", import.meta.url);
const files = readdirSync(dir)
  .filter((f) => f.endsWith(".ts") && f !== "index.ts")
  .filter((f) => /export const pages\b/.test(readFileSync(new URL(f, dir), "utf8")))
  .sort();
const id = (f) => "p_" + f.replace(/\.ts$/, "").replace(/\W/g, "_");
const out = [
  "// AUTO-GENERATED by scripts/gen-pages-index.mjs — do not edit.",
  'import type { PageContent } from "../types";',
  ...files.map((f) => `import { pages as ${id(f)} } from "./${f.replace(/\.ts$/, "")}";`),
  "",
  `export const allPages: PageContent[] = [${files.map(id).join(", ")}].flat();`,
  "",
].join("\n");
writeFileSync(new URL("index.ts", dir), out);
console.log(`pages index: ${files.length} files`);
